/*
 * Photography used on the site. Every image is an openly licensed photograph from Wikimedia Commons.
 * Files were resized, and some were cropped, and re-encoded as JPEG for the web. The licence, author and source
 * for each are listed on /credits, as the CC BY and CC BY-SA licences require.
 * Generated by the photo-sourcing step; edit captions and alt text freely.
 */
export interface Photo {
  id: string;
  src: string;
  width: number;
  height: number;
  alt: string;
  /** Short place caption shown on the image. */
  caption: string;
  author: string;
  license: string;
  licenseUrl: string;
  /** Wikimedia Commons description page. */
  source: string;
  file: string;
  /** Tiny base64 JPEG used as a blur-up placeholder. */
  blur: string;
}

